-- ==============================================================================
-- SKEMA & SEED DATA SUPABASE POSTGRESQL TERBARU
-- SMK NEGERI 2 MAGELANG
-- 33 Kelas (PPLG 1-3, PM 1-2, AKL 1-3, MPLB 1-3 X/XI/XII) | 1172 Siswa | 594 Jadwal | 3516 Nilai
-- ==============================================================================

-- 1. STRUKTUR TABEL DDL
CREATE TABLE IF NOT EXISTS public.jurusan (
    id_jurusan SERIAL PRIMARY KEY,
    kode_jurusan VARCHAR(10) UNIQUE NOT NULL,
    nama_jurusan VARCHAR(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.kelas (
    id_kelas SERIAL PRIMARY KEY,
    nama_kelas VARCHAR(50) NOT NULL,
    tingkat VARCHAR(10) NOT NULL CHECK (tingkat IN ('X', 'XI', 'XII')),
    id_jurusan INT REFERENCES public.jurusan(id_jurusan) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.guru (
    id_guru SERIAL PRIMARY KEY,
    nip VARCHAR(25) UNIQUE NOT NULL,
    nama_guru VARCHAR(100) NOT NULL,
    email VARCHAR(100) UNIQUE,
    no_hp VARCHAR(20) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.mata_pelajaran (
    id_mapel SERIAL PRIMARY KEY,
    kode_mapel VARCHAR(15) UNIQUE NOT NULL,
    nama_mapel VARCHAR(150) NOT NULL,
    kelompok VARCHAR(50) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.siswa (
    nis VARCHAR(20) PRIMARY KEY,
    nama_siswa VARCHAR(100) NOT NULL,
    jenis_kelamin VARCHAR(2) NOT NULL CHECK (jenis_kelamin IN ('L', 'P')),
    tanggal_lahir DATE NOT NULL,
    alamat TEXT NOT NULL,
    no_hp_ortu VARCHAR(20),
    id_kelas INT REFERENCES public.kelas(id_kelas) ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS public.tahun_ajaran (
    id_tahun_ajaran SERIAL PRIMARY KEY,
    tahun_ajaran VARCHAR(10) NOT NULL,
    semester VARCHAR(10) NOT NULL CHECK (semester IN ('Ganjil', 'Genap')),
    status VARCHAR(20) NOT NULL DEFAULT 'Aktif' CHECK (status IN ('Aktif', 'Tidak Aktif'))
);

CREATE TABLE IF NOT EXISTS public.jadwal (
    id_jadwal SERIAL PRIMARY KEY,
    id_guru INT REFERENCES public.guru(id_guru) ON DELETE CASCADE,
    id_mapel INT REFERENCES public.mata_pelajaran(id_mapel) ON DELETE CASCADE,
    id_kelas INT REFERENCES public.kelas(id_kelas) ON DELETE CASCADE,
    hari VARCHAR(15) NOT NULL CHECK (hari IN ('Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu')),
    jam_mulai TIME NOT NULL,
    jam_selesai TIME NOT NULL,
    ruang VARCHAR(50) DEFAULT 'Ruang Teori'
);

CREATE TABLE IF NOT EXISTS public.nilai (
    id_nilai SERIAL PRIMARY KEY,
    nis VARCHAR(20) REFERENCES public.siswa(nis) ON DELETE CASCADE,
    id_mapel INT REFERENCES public.mata_pelajaran(id_mapel) ON DELETE CASCADE,
    id_guru INT REFERENCES public.guru(id_guru) ON DELETE CASCADE,
    id_tahun_ajaran INT REFERENCES public.tahun_ajaran(id_tahun_ajaran) ON DELETE CASCADE,
    nilai_tugas NUMERIC(5,2) DEFAULT 0.00,
    nilai_uts NUMERIC(5,2) DEFAULT 0.00,
    nilai_uas NUMERIC(5,2) DEFAULT 0.00,
    nilai_akhir NUMERIC(5,2) DEFAULT 0.00
);

CREATE TABLE IF NOT EXISTS public.presensi (
    id_presensi SERIAL PRIMARY KEY,
    nis VARCHAR(20) REFERENCES public.siswa(nis) ON DELETE CASCADE,
    id_kelas INT REFERENCES public.kelas(id_kelas) ON DELETE CASCADE,
    tanggal DATE NOT NULL DEFAULT CURRENT_DATE,
    status VARCHAR(10) NOT NULL CHECK (status IN ('Hadir', 'Sakit', 'Izin', 'Alpa')),
    keterangan TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT uq_siswa_presensi UNIQUE (nis, tanggal)
);

CREATE TABLE IF NOT EXISTS public.remedial (
    id_remedial SERIAL PRIMARY KEY,
    id_nilai INT REFERENCES public.nilai(id_nilai) ON DELETE CASCADE,
    nis VARCHAR(20) REFERENCES public.siswa(nis) ON DELETE CASCADE,
    id_mapel INT REFERENCES public.mata_pelajaran(id_mapel) ON DELETE CASCADE,
    id_tahun_ajaran INT REFERENCES public.tahun_ajaran(id_tahun_ajaran) ON DELETE CASCADE,
    nilai_awal NUMERIC(5,2) NOT NULL,
    nilai_remedial NUMERIC(5,2) NOT NULL CHECK (nilai_remedial >= 0 AND nilai_remedial <= 100),
    tanggal DATE NOT NULL DEFAULT CURRENT_DATE,
    catatan TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.user_profiles (
    id VARCHAR(64) PRIMARY KEY,
    email VARCHAR(100) UNIQUE NOT NULL,
    nama_lengkap VARCHAR(100) NOT NULL,
    role VARCHAR(20) NOT NULL CHECK (role IN ('admin', 'guru', 'siswa')),
    identifier VARCHAR(50) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.auth_audit_logs (
    id VARCHAR(64) PRIMARY KEY,
    timestamp TIMESTAMPTZ DEFAULT NOW(),
    action VARCHAR(30) NOT NULL,
    user_id VARCHAR(64) NOT NULL,
    role VARCHAR(20),
    details TEXT NOT NULL,
    ip_mock VARCHAR(45)
);

-- INDEXES
CREATE INDEX IF NOT EXISTS idx_siswa_kelas ON public.siswa(id_kelas);
CREATE INDEX IF NOT EXISTS idx_nilai_siswa ON public.nilai(nis);
CREATE INDEX IF NOT EXISTS idx_nilai_mapel ON public.nilai(id_mapel);
CREATE INDEX IF NOT EXISTS idx_jadwal_hari ON public.jadwal(hari, id_kelas);
CREATE INDEX IF NOT EXISTS idx_presensi_lookup ON public.presensi(tanggal, id_kelas);
CREATE INDEX IF NOT EXISTS idx_remedial_nilai ON public.remedial(id_nilai);
CREATE INDEX IF NOT EXISTS idx_audit_timestamp ON public.auth_audit_logs(timestamp DESC);

-- RLS
ALTER TABLE public.siswa ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.guru ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kelas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.jurusan ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mata_pelajaran ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.jadwal ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tahun_ajaran ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.nilai ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.presensi ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.remedial ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.auth_audit_logs ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for jurusan') THEN
        CREATE POLICY "Public read for jurusan" ON public.jurusan FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for kelas') THEN
        CREATE POLICY "Public read for kelas" ON public.kelas FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for mapel') THEN
        CREATE POLICY "Public read for mapel" ON public.mata_pelajaran FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for tahun_ajaran') THEN
        CREATE POLICY "Public read for tahun_ajaran" ON public.tahun_ajaran FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for jadwal') THEN
        CREATE POLICY "Public read for jadwal" ON public.jadwal FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for guru') THEN
        CREATE POLICY "Public read for guru" ON public.guru FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for siswa') THEN
        CREATE POLICY "Public read for siswa" ON public.siswa FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for nilai') THEN
        CREATE POLICY "Public read for nilai" ON public.nilai FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for presensi') THEN
        CREATE POLICY "Public read for presensi" ON public.presensi FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for remedial') THEN
        CREATE POLICY "Public read for remedial" ON public.remedial FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for user_profiles') THEN
        CREATE POLICY "Public read for user_profiles" ON public.user_profiles FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for audit_logs') THEN
        CREATE POLICY "Public read for audit_logs" ON public.auth_audit_logs FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Allow mutations for nilai') THEN
        CREATE POLICY "Allow mutations for nilai" ON public.nilai FOR ALL USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Allow mutations for siswa') THEN
        CREATE POLICY "Allow mutations for siswa" ON public.siswa FOR ALL USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Allow mutations for guru') THEN
        CREATE POLICY "Allow mutations for guru" ON public.guru FOR ALL USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Allow mutations for jadwal') THEN
        CREATE POLICY "Allow mutations for jadwal" ON public.jadwal FOR ALL USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Allow insert presensi') THEN
        CREATE POLICY "Allow insert presensi" ON public.presensi FOR INSERT WITH CHECK (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Allow update presensi') THEN
        CREATE POLICY "Allow update presensi" ON public.presensi FOR UPDATE USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Allow insert remedial') THEN
        CREATE POLICY "Allow insert remedial" ON public.remedial FOR INSERT WITH CHECK (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Allow update remedial') THEN
        CREATE POLICY "Allow update remedial" ON public.remedial FOR UPDATE USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Allow insert profiles') THEN
        CREATE POLICY "Allow insert profiles" ON public.user_profiles FOR INSERT WITH CHECK (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Allow insert audit_logs') THEN
        CREATE POLICY "Allow insert audit_logs" ON public.auth_audit_logs FOR INSERT WITH CHECK (true);
    END IF;
END $$;

